def task_func(myString, API_KEY):
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    found_urls = re.findall(url_pattern, myString)

    unique_domains = set()
    for url in found_urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.hostname:
            unique_domains.add(parsed.hostname)

    geolocation_results = {}
    for domain in unique_domains:
        try:
            api_url = f"http://ip-api.com/json/{domain}"
            response = requests.get(api_url, params={'key': API_KEY})
            if response.status_code == 200:
                geolocation_results[domain] = json.loads(response.text)
            else:
                geolocation_results[domain] = None
        except Exception:
            geolocation_results[domain] = None

    return geolocation_results

