            raise ValueError("Malformed entry in JSON data")

        country = entry["Country"]
        population = entry["Population"]

        if not isinstance(country, str):
            raise ValueError("Non-string country names are not allowed")

        if not isinstance(population, (int, float)) or isinstance(population, bool):
            raise ValueError("Non-numeric population value")

        if population < 0:
            raise ValueError("Negative population values are not allowed")

        processed_data.append({
            "Country": country,
            "Population": math.floor(population)
        })

    df = pd.DataFrame(processed_data, columns=["Country", "Population"])

    if not os.path.exists(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except Exception:
            raise IOError("Could not create output directory")

    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("The file could not be written to the specified directory")

    return os.path.abspath(file_path), df

